// ── SVG Radar Chart (Pentagonal 5 Ejes / Dinámico) ──────────────
export const SvgRadar = ({ data, size = 320 }) => {
  const { darkMode } = useTheme();
  const { isEn } = useTranslation();
  if (!data || data.length === 0) return null;
  const padX = 95;
  const padY = 32;
  const svgW = size + padX * 2;
  const svgH = size + padY * 2;
  const cx = svgW / 2;
  const cy = svgH / 2;
  const r  = (size / 2) * 0.58;
  const n  = data.length;
  const hasData = data.some(d => d.value > 0);

  const angleOf = i => (2 * Math.PI * i) / n - Math.PI / 2;

  const ringStroke = darkMode ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.18)';
  const labelColor = darkMode ? '#FFFFFF' : '#0F172A';
  const valColor = darkMode ? '#FBBF24' : '#B45309';

  // Grid rings
  const rings = [20, 40, 60, 80, 100].map(pct => (
    <polygon
      key={pct}
      points={Array.from({ length: n }, (_, i) => {
        const a = angleOf(i);
        const rr = r * (pct / 100);
        return `${cx + rr * Math.cos(a)},${cy + rr * Math.sin(a)}`;
      }).join(' ')}
      fill="none"
      stroke={ringStroke}
      strokeWidth={pct === 100 ? 1.5 : 0.8}
      strokeDasharray={pct === 100 ? 'none' : '3,3'}
    />
  ));

  // Axis lines
  const axes = Array.from({ length: n }, (_, i) => {
    const a = angleOf(i);
    return (
      <line
        key={i}
        x1={cx} y1={cy}
        x2={cx + r * Math.cos(a)} y2={cy + r * Math.sin(a)}
        stroke={ringStroke} strokeWidth={1}
      />
    );
  });

  // Data polygon
  const dataPoints = data.map((d, i) => {
    const a  = angleOf(i);
    const rr = r * Math.min(1, Math.max(5, (d.value || 0)) / 100);
    return { x: cx + rr * Math.cos(a), y: cy + rr * Math.sin(a) };
  });
  const polyStr = dataPoints.map(p => `${p.x},${p.y}`).join(' ');

  // Labels around the radar
  const labels = data.map((d, i) => {
    const a = angleOf(i);
    const labelR = r + 22;
    const lx = cx + labelR * Math.cos(a);
    const ly = cy + labelR * Math.sin(a);

    let textAnchor = 'middle';
    if (Math.cos(a) > 0.25) textAnchor = 'start';
    else if (Math.cos(a) < -0.25) textAnchor = 'end';

    const radarLabelMap = {
      'FÍSICO': isEn ? 'PHYSICAL' : 'FÍSICO',
      'TÉCNICA': isEn ? 'TECHNICAL' : 'TÉCNICA',
      'TÁCTICA': isEn ? 'TACTICAL' : 'TÁCTICA',
      'MENTAL': isEn ? 'MENTAL' : 'MENTAL',
      'ASISTENCIA': isEn ? 'ATTENDANCE' : 'ASISTENCIA'
    };
    const rawLabel = d.subject || d.label || (isEn ? `Axis ${i+1}` : `Eje ${i+1}`);
    const labelText = radarLabelMap[rawLabel.toUpperCase()] || rawLabel;

    return (
      <g key={labelText + i}>
        <text
          x={lx}
          y={ly - 4}
          textAnchor={textAnchor}
          dominantBaseline="middle"
          fill={labelColor}
          style={{ fontSize: 11, fontWeight: 900, fontFamily: 'Outfit, sans-serif' }}
        >
          {labelText}
        </text>
        <text
          x={lx}
          y={ly + 8}
          textAnchor={textAnchor}
          dominantBaseline="middle"
          fill={valColor}
          style={{ fontSize: 10, fontWeight: 800, fontFamily: 'Outfit, sans-serif' }}
        >
          ({d.value || 0})
        </text>
      </g>
    );
  });

  return (
    <svg
      viewBox={`0 0 ${svgW} ${svgH}`}
      style={{
        width: '100%',
        maxWidth: `${svgW}px`,
        height: 'auto',
        overflow: 'visible',
        display: 'block',
        margin: '0 auto'
      }}
    >
      {rings}
      {axes}
      {hasData && (
        <>
          <polygon
            points={polyStr}
            fill={darkMode ? 'rgba(76, 175, 125, 0.35)' : 'rgba(27, 58, 45, 0.25)'}
            fillOpacity={0.4}
            stroke={darkMode ? '#FBBF24' : '#D4A843'}
            strokeWidth={2.5}
          />
          {dataPoints.map((p, i) => (
            <circle
              key={i}
              cx={p.x}
              cy={p.y}
              r={4}
              fill={darkMode ? '#FBBF24' : '#1B3A2D'}
              stroke="#FFF"
              strokeWidth={1.5}
            />
          ))}
        </>
      )}
      {labels}
    </svg>
  );
};


