// ── Modal principal ──────────────────────────────────────────────────────────
const PlayerAnalyticsModal = ({
  player,
  tests = [],
  historyData = {},
  onClose,
  onExportPDF,
  onDeleteLastEval,
  onDeleteAllEvals,
  onResetPlayerTests,
  activeTeam = {},
  playerEvals: incomingPlayerEvals
}) => {
  const { t, isEn } = useTranslation();
  const contentRef = useRef(null);

  if (!player) return null;

  // ── Cálculo canónico unificado de los 5 ejes deportivos (1:1 con Portal del Jugador) ──
  let playerEvals = incomingPlayerEvals;
  if (!playerEvals || playerEvals.length === 0) {
    playerEvals = [];
    Object.entries(historyData[player?.id] || {}).forEach(([testId, hList]) => {
      if (hList && hList.length > 0) {
        const last = hList[hList.length - 1];
        playerEvals.push({ testId, val: last.val, date: last.date, ...(last.raw || {}) });
      }
    });
  }

  const scores = calculatePlayerPerformanceScores(playerEvals, player, {
    attendancePct: player?.attendancePct ? Number(player.attendancePct) : 0,
    matchRating: player?.notaMedia || null
  });
  const { fis, tec, psi, soc, tactica, asistencia, entrenamiento, overall, testCount: totalTests, radarData6 } = scores;
  const radarData = radarData6 || scores.radarData;

  const initials = (player.name || '').split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);

  // Tests con historial del jugador
  const testsWithData = tests.filter(t => (historyData[player.id]?.[t.id] || []).length > 0);

  const handleExport = async () => {
    if (!contentRef.current) return;
    try {
      // Ocultar botones antes de exportar
      const exportBtn = contentRef.current.querySelector('button');
      const closeBtn = contentRef.current.querySelectorAll('button')[1];
      const deleteButtons = contentRef.current.querySelectorAll('.delete-actions');
      
      if (exportBtn) exportBtn.style.display = 'none';
      if (closeBtn) closeBtn.style.display = 'none';
      deleteButtons.forEach(btn => { btn.style.display = 'none'; });

      const { jsPDF } = await import('jspdf');
      const html2canvas = (await import('html2canvas')).default;
      const { drawPdfHeader, drawPdfFooter, captureElementHighContrast } = await import('../utils/pdfTheme');

      const doc = new jsPDF('p', 'mm', 'a4');
      const pdfWidth = doc.internal.pageSize.getWidth();
      const pdfHeight = doc.internal.pageSize.getHeight();
      
      const capturarGrafica = async (elementId) => {
        const element = document.getElementById(elementId);
        if (!element) return null;
        const base64 = await captureElementHighContrast(html2canvas, element, 2);
        if (!base64) return null;
        return {
          img: base64,
          w: element.offsetWidth || 800,
          h: element.offsetHeight || 400
        };
      };

      drawPdfHeader(doc, isEn ? `INDIVIDUAL REPORT: ${player.name}` : `INFORME INDIVIDUAL: ${player.name}`, `#${player.number || '-'} · ${player.position || (isEn ? 'Player' : 'Jugador')}`, pdfWidth);
      let yPos = 44;

      // 2. Radar y Stats
      const radarData = await capturarGrafica('player-radar-stats');
      if (radarData) {
        const imgHeight = (radarData.h * (pdfWidth - 24)) / radarData.w;
        doc.addImage(radarData.img, 'PNG', 12, yPos, pdfWidth - 24, imgHeight);
        yPos += imgHeight + 10;
      }

      // 3. Evolución
      const evoData = await capturarGrafica('player-evolution-charts');
      if (evoData) {
        const imgHeight = (evoData.h * (pdfWidth - 24)) / evoData.w;
        if (yPos + imgHeight > pdfHeight - 20) {
          doc.addPage();
          yPos = 44;
          drawPdfHeader(doc, isEn ? `INDIVIDUAL REPORT: ${player.name}` : `INFORME INDIVIDUAL: ${player.name}`, isEn ? 'Performance Evolution' : 'Evolución de Rendimiento', pdfWidth);
        }
        doc.addImage(evoData.img, 'PNG', 12, yPos, pdfWidth - 24, imgHeight);
      }

      // Pie de página unificado
      const totalPages = doc.internal.getNumberOfPages();
      for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        drawPdfFooter(doc, pdfWidth, pdfHeight, i, totalPages);
      }

      // Restaurar botones
      if (exportBtn) exportBtn.style.display = 'block';
      if (closeBtn) closeBtn.style.display = 'block';
      deleteButtons.forEach(btn => { btn.style.display = 'flex'; });

      const pdfBase64 = doc.output('dataurlstring').split(',')[1];
      await downloadPDF(pdfBase64, `${isEn ? 'Player_Report' : 'Informe_Jugador'}_${player.name.replace(/\s+/g, '_')}.pdf`);
    } catch (e) {
      console.error("Error generating pdf:", e);
      alert(isEn ? 'Error exporting PDF' : 'Error al exportar PDF');
    }
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 9999,
      background: 'rgba(27, 58, 45, 0.75)', backdropFilter: 'blur(6px)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      padding: '16px'
    }} onClick={onClose}>
      <div
        ref={contentRef}
        style={{
          background: '#FAFAF7',
          borderRadius: 20,
          width: '100%',
          maxWidth: 1000,
          maxHeight: '92vh',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
          boxShadow: '0 25px 60px rgba(0,0,0,0.35)'
        }}
        onClick={e => e.stopPropagation()}
      >
        {/* Header */}
        <div style={{
          background: C_DARK, color: '#FFF',
          padding: '20px 28px',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          flexShrink: 0
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
            <div style={{
              width: 52, height: 52, borderRadius: '50%',
              background: C_GOLD, color: C_DARK,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 20, fontWeight: 800
            }}>
              {initials}
            </div>
            <div>
              <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: '#FFF' }}>{player.name}</h2>
              <p style={{ margin: 0, fontSize: 13, color: 'rgba(255,255,255,0.65)' }}>
                #{player.number} · {player.position} · {totalTests} {isEn ? 'evaluations recorded' : 'evaluaciones registradas'}
              </p>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            {onResetPlayerTests && (
              <button
                type="button"
                onClick={() => onResetPlayerTests(player.id)}
                style={{
                  background: 'rgba(239, 68, 68, 0.15)',
                  color: '#EF4444',
                  border: '1px solid rgba(239, 68, 68, 0.4)',
                  borderRadius: 8,
                  padding: '9px 14px',
                  fontWeight: 700,
                  fontSize: 12.5,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6
                }}
                title={isEn ? "Reset questionnaires and clear evaluations for a new test" : "Renovar cuestionarios y limpiar evaluaciones para una nueva prueba"}
              >
                🔄 {isEn ? 'Renew Tests' : 'Renovar Tests'}
              </button>
            )}
            <button
              onClick={handleExport}
              style={{
                background: C_GOLD, color: C_DARK, border: 'none',
                borderRadius: 8, padding: '10px 18px',
                fontWeight: 700, fontSize: 13, cursor: 'pointer'
              }}
            >
              📄 {isEn ? 'Export PDF' : 'Exportar PDF'}
            </button>
            <button
              onClick={onClose}
              style={{
                background: 'rgba(255,255,255,0.15)', color: '#FFF', border: 'none',
                borderRadius: 8, padding: '10px 16px',
                fontWeight: 700, fontSize: 16, cursor: 'pointer'
              }}
            >
              ✕
            </button>
          </div>
        </div>

        {/* Body */}
        <div style={{ overflowY: 'auto', flex: 1, padding: '24px 28px' }}>

          {/* Top section: Radar + Stats */}
          <div id="player-radar-stats" style={{
            display: 'flex', gap: 28, marginBottom: 32,
            flexWrap: 'wrap'
          }}>
            {/* Radar */}
            <div style={{
              background: C_BEIGE, borderRadius: 16,
              padding: '20px 24px',
              display: 'flex', flexDirection: 'column',
              alignItems: 'center', gap: 12,
              flexShrink: 0
            }}>
              <h3 style={{ margin: 0, color: C_DARK, fontSize: 14, fontWeight: 700, letterSpacing: 1 }}>
                {isEn ? 'PERFORMANCE PROFILE' : 'PERFIL DE RENDIMIENTO'}
              </h3>
              <SvgRadar data={radarData} size={300} />
            </div>

            {/* Stats panel */}
            <div style={{ flex: 1, minWidth: 240, display: 'flex', flexDirection: 'column', gap: 16 }}>
              {/* Overall */}
              <div style={{
                background: C_DARK, borderRadius: 16, padding: '20px 24px',
                display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4
              }}>
                <span style={{ color: 'rgba(255,255,255,0.6)', fontSize: 12, letterSpacing: 2 }}>
                  {isEn ? 'OVERALL RATING' : 'ÍNDICE GLOBAL'}
                </span>
                <span style={{ fontSize: 56, fontWeight: 900, color: C_GOLD, lineHeight: 1 }}>{overall || '--'}</span>
                <span style={{ color: 'rgba(255,255,255,0.5)', fontSize: 12 }}>
                  {isEn ? 'out of 100' : 'sobre 100'}
                </span>
              </div>
              {/* Attribute badges (6 ejes canónicos del perfil integral) */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(95px, 1fr))', gap: 10 }}>
                {[
                  { label: isEn ? 'PHYSICAL' : 'FÍSICO', value: fis, color: '#4CAF7D' },
                  { label: isEn ? 'TECHNICAL' : 'TÉCNICA', value: tec, color: '#2E7D5C' },
                  { label: isEn ? 'TACTICAL' : 'TÁCTICA', value: tactica, color: '#10B981' },
                  { label: isEn ? 'MENTAL' : 'MENTAL', value: psi, color: C_GOLD },
                  { label: isEn ? 'ATTENDANCE' : 'ASISTENCIA', value: asistencia, color: '#8B5CF6' },
                  { label: isEn ? 'TRAINING' : 'ENTRENAMIENTO', value: entrenamiento, color: '#D4A843' },
                ].map(({ label, value, color }) => (
                  <div key={label} style={{
                    background: '#FFF', borderRadius: 12, padding: '12px 8px',
                    border: `2px solid ${C_BORDER}`, textAlign: 'center'
                  }}>
                    <div style={{ fontSize: 10, color: '#7A7065', letterSpacing: 0.5, marginBottom: 4, fontWeight: 800 }}>{label}</div>
                    <div style={{ fontSize: 24, fontWeight: 800, color }}>{value || '--'}</div>
                    {/* Progress bar */}
                    <div style={{ height: 4, background: C_BORDER, borderRadius: 2, marginTop: 6, overflow: 'hidden' }}>
                      <div style={{
                        height: '100%', width: `${value}%`,
                        background: color, borderRadius: 2,
                        transition: 'width 1s ease'
                      }} />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Evolution charts */}
          {testsWithData.length === 0 ? (
            <div style={{
              background: C_BEIGE, borderRadius: 16, padding: 40,
              textAlign: 'center', color: '#7A7065'
            }}>
              <p style={{ fontSize: 18 }}>
                {isEn 
                  ? <>📊 No evaluations yet. Use the <strong>"🎯 Demo Data"</strong> button to view charts.</>
                  : <>📊 Sin evaluaciones aún. Usa el botón <strong>"🎯 Datos Demo"</strong> para ver las gráficas.</>}
              </p>
            </div>
          ) : (
            <>
              <h3 style={{ color: C_DARK, fontSize: 14, fontWeight: 700, letterSpacing: 1, marginBottom: 16 }}>
                {isEn ? 'PROGRESS BY TEST' : 'EVOLUCIÓN POR PRUEBA'}
              </h3>
              <div id="player-evolution-charts" style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
                gap: 20
              }}>
                {testsWithData.map(t => {
                  const history = (historyData[player.id]?.[t.id] || []).map(h => ({
                    ...h,
                    val: parseFloat(String(h.val).replace(',', '.')) || 0
                  }));
                  const vals = history.map(h => h.val);
                  const first = vals[0];
                  const last = vals[vals.length - 1];
                  const isTime = t.unit === 'seg';
                  const diff = last - first;
                  const improved = vals.length > 1 && (isTime ? diff < 0 : diff > 0);
                  const noChange = vals.length < 2 || diff === 0;

                  return (
                    <div key={t.id} style={{
                      background: '#FFF', borderRadius: 14, padding: '16px',
                      border: `1px solid ${C_BORDER}`,
                      boxShadow: '0 2px 8px rgba(0,0,0,0.04)'
                    }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 10 }}>
                        <div>
                          <div style={{ fontSize: 11, color: '#7A7065', marginBottom: 2 }}>
                            {isEn ? (CATEGORY_MAP[String(t.category).trim().toLowerCase()] || t.category) : t.category}
                          </div>
                          <div style={{ fontSize: 13, fontWeight: 700, color: C_DARK }}>
                            {isEn ? (TEST_NAME_MAP[t.name] || t.name) : t.name}
                          </div>
                        </div>
                        {noChange ? (
                          <span style={{
                            fontSize: 11, background: C_BEIGE, color: '#7A7065',
                            borderRadius: 20, padding: '3px 10px', alignSelf: 'flex-start', fontWeight: 600
                          }}>
                            {last} {t.unit}
                          </span>
                        ) : (
                          <span style={{
                            fontSize: 11,
                            background: improved ? '#E8F5E9' : '#FFEBEE',
                            color: improved ? '#2E7D32' : '#C62828',
                            borderRadius: 20, padding: '3px 10px', alignSelf: 'flex-start', fontWeight: 700
                          }}>
                            {improved ? '▲' : '▼'} {Math.abs((diff / first) * 100).toFixed(1)}%
                          </span>
                        )}
                      </div>
                      <MiniLineChart data={history} isTime={isTime} />
                      {/* Progress bar */}
                      <div style={{ marginTop: 10 }}>
                        <div style={{ height: 6, background: C_BEIGE, borderRadius: 3, overflow: 'hidden' }}>
                          <div style={{
                            height: '100%',
                            width: `${Math.min(100, Math.abs(last))}%`,
                            background: C_GOLD, borderRadius: 3
                          }} />
                        </div>
                      </div>

                      {/* Delete Actions */}
                      <div className="delete-actions" style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        marginTop: 12,
                        paddingTop: 10,
                        borderTop: `1px solid ${C_BORDER}`
                      }}>
                        <button
                          onClick={() => onDeleteLastEval?.(player.id, t.id)}
                          style={{
                            background: 'none', border: 'none', color: '#C62828',
                            fontSize: 11, cursor: 'pointer', fontWeight: 600, padding: 0
                          }}
                        >
                          🗑️ {isEn ? 'Delete latest' : 'Eliminar último'}
                        </button>
                        <button
                          onClick={() => onDeleteAllEvals?.(player.id, t.id)}
                          style={{
                            background: 'none', border: 'none', color: '#C62828',
                            fontSize: 11, cursor: 'pointer', fontWeight: 600, padding: 0, opacity: 0.8
                          }}
                        >
                          💥 {isEn ? 'Delete all' : 'Eliminar todos'}
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default PlayerAnalyticsModal;
